// Merge kattar into essentials so both sets contain topic-wise questions
function mergeMoleConcept(a: SetData, b: SetData): SetData {
  const map = new Map<string, typeof a.subtopics[0]>();
  for (const st of a.subtopics) map.set(st.name, { name: st.name, questions: [...st.questions] });
  for (const st of b.subtopics) {
    const ex = map.get(st.name);
    if (ex) ex.questions.push(...st.questions);
    else map.set(st.name, { name: st.name, questions: [...st.questions] });
  }
  return { subtopics: Array.from(map.values()) };
}

const moleConceptMerged: SetData = mergeMoleConcept(moleConceptNcertEssentials, kattarMoleConceptTopicwise);
export const moleConceptStandard: SetData = kattarMoleConceptTopicwise;
// Use merged for NCERT-Essentials (keeps original + adds kattar topicwise)
Object.assign(moleConceptNcertEssentials, moleConceptMerged);
